CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS categories (id TEXT PRIMARY KEY, name TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, included_count INTEGER NOT NULL DEFAULT 0, extra_cents INTEGER NOT NULL DEFAULT 0, selection_mode TEXT NOT NULL DEFAULT 'multi' CHECK(selection_mode IN ('single','multi','sauce')), active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS ingredients (id TEXT PRIMARY KEY, category_id TEXT NOT NULL REFERENCES categories(id), name TEXT NOT NULL, available INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0, allergens TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS orders (id INTEGER PRIMARY KEY AUTOINCREMENT, public_id TEXT NOT NULL UNIQUE, public_token TEXT NOT NULL UNIQUE, customer_name TEXT NOT NULL, phone TEXT NOT NULL, pickup_date TEXT NOT NULL, pickup_time TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','preparing','ready','completed','rejected','cancelled')), items_json TEXT NOT NULL, total_cents INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), whatsapp_sent_at TEXT, email_status TEXT NOT NULL DEFAULT 'not_configured', payment_status TEXT NOT NULL DEFAULT 'unpaid', admin_notes TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS ix_orders_day ON orders(pickup_date,pickup_time,status);
CREATE INDEX IF NOT EXISTS ix_orders_created ON orders(created_at);
CREATE TABLE IF NOT EXISTS login_attempts (ip_hash TEXT PRIMARY KEY, failures INTEGER NOT NULL DEFAULT 0, last_failure INTEGER NOT NULL DEFAULT 0);
